from typing import List, Sequence, Tuple

def anti_diagonal(table: Sequence[Sequence[int]]) -> List[int]:
    n = len(table)
    if any(len(row) != n for row in table):
        raise ValueError("square table required")
    return [1 - table[i][i] for i in range(n)]

def demonstrate() -> None:
    table = [[(i * 3 + j * 5 + i * j) % 2 for j in range(8)] for i in range(8)]
    d = anti_diagonal(table)
    witnesses: List[Tuple[int, int, int]] = [(i, table[i][i], d[i]) for i in range(8)]
    for i, row_bit, diagonal_bit in witnesses:
        print(i, row_bit, diagonal_bit, row_bit != diagonal_bit)
    assert all(table[i][i] != d[i] for i in range(8))

if __name__ == "__main__":
    demonstrate()

from collections import defaultdict
from itertools import product
from typing import Callable, DefaultDict, List, Sequence, Tuple

Word = Tuple[str, ...]

def forget(word: Sequence[str], retain: Callable[[str], bool]) -> Word:
    return tuple(letter for letter in word if retain(letter))

def demonstrate() -> None:
    alphabet = ("a", "b", "x")
    retain = lambda letter: letter != "x"
    classes: DefaultDict[Word, List[Word]] = defaultdict(list)
    for length in range(4):
        for word in product(alphabet, repeat=length):
            classes[forget(word, retain)].append(word)
    for observable, members in sorted(classes.items(), key=lambda item: (len(item[0]), item[0])):
        print(observable, "<-", members)
    u, v = ("a", "x"), ("x", "b")
    assert forget(u + v, retain) == forget(u, retain) + forget(v, retain)

if __name__ == "__main__":
    demonstrate()

